pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut pairs: Vec<(i64, i64)> = match input {
        serde_json::Value::Array(arr) => {
            let mut vec = Vec::with_capacity(arr.len());
            for item in arr {
                if let serde_json::Value::Array([priority, id]) = item {
                    let priority = priority.as_i64().unwrap();
                    let id = id.as_i64().unwrap();
                    vec.push((priority, id));
                }
            }
            vec
        }
        _ => return serde_json::json!([]),
    };

    // Sort by decreasing priority, then by increasing id on ties
    pairs.sort_by(|a, b| {
        if a.0 != b.0 {
            b.0.cmp(&a.0)
        } else {
            a.1.cmp(&b.1)
        }
    });

    // Extract ids in sorted order
    let result: Vec<i64> = pairs.into_iter().map(|(_, id)| id).collect();

    serde_json::json!(result)
}
